mapper.select:
SELECT s.id AS scheduleId, s.visit_date AS visitDate, s.period, s.slot_type AS slotType, s.fee_cents AS feeCents, s.total_slots AS totalSlots, s.released_slots AS releasedSlots, s.booked_slots AS bookedSlots, s.status, s.release_at AS releaseAt, d.name AS doctorName, d.title, dep.name AS departmentName FROM t_schedule s JOIN t_doctor d ON d.id = s.doctor_id JOIN t_department dep ON dep.id = s.department_id
s.visit_date = #{date}
ORDER BY s.visit_date, s.id

SELECT id, patient_id AS patientId, device_id AS deviceId, level, action, reason,
       created_at AS createdAt
  FROM t_risk_event ORDER BY id DESC LIMIT #{limit}

SELECT total_slots AS totalSlots, released_slots AS releasedSlots,
       booked_slots AS bookedSlots, status
  FROM t_schedule WHERE id=#{scheduleId}
